UPDATE CUS_PERF_LIST
  SET HUM_FLAG = HUM_FLAG * #{ humFlag,jdbcType=DECIMAL },
  GROUP_FLAG = GROUP_FLAG * #{ groupFlag,jdbcType=DECIMAL },
  DEPT_FLAG = DEPT_FLAG * #{ deptFlag,jdbcType=DECIMAL }
where PERF_MONTH = #{ perfMonth, jdbcType = VARCHAR } AND PLO_NUM #{ ploNum, jdbcType = VARCHAR }
